public sealed record OrderRequest(int ProductId, int Quantity);

public static IResult ValidateOrder(OrderRequest request)
{
    var errors = new Dictionary<string, string[]>();
    if (request.ProductId <= 0)
        errors["productId"] = ["A valid product is required."];
    if (request.Quantity is < 1 or > 100)
        errors["quantity"] = ["Quantity must be between 1 and 100."];

    return errors.Count > 0
        ? Results.ValidationProblem(errors)
        : Results.Ok(new { valid = true });
}

