using Microsoft.AspNetCore.Authorization;
using System.Security.Claims;

public sealed record Expense(string OwnerId, decimal Amount);
public sealed class OwnerRequirement : IAuthorizationRequirement;

public sealed class OwnerHandler : AuthorizationHandler<OwnerRequirement, Expense>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context, OwnerRequirement requirement, Expense resource)
    {
        var userId = context.User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (userId is not null && userId == resource.OwnerId)
            context.Succeed(requirement);
        return Task.CompletedTask;
    }
}

